{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (≤ 0.00) to account for risk aversion or market cooling.",
    "Reduce forecast overshoots following sharp upward spikes in price (e.g., > +5% from prior day) by 10–15% to avoid overreaction.",
    "Apply mean reversion bias: if forecast deviates > ±3% from 14-day moving average, adjust toward it with a decay factor of 0.85 per day.",
    "For 30-day horizon, penalize high variance in forecast tails (especially > 10% deviation from true) by smoothing with prior 7-day average.",
    "If sentiment history shows sustained positive momentum (≥ 0.50 for 3 consecutive days), slightly increase forecast bias upward, but cap at +2% to avoid overfitting."
  ]
}
